//#region src/utils.ts
async function signData(addressHex, payload, privateKey) {
	const { Label, CBORValue, COSESign1Builder, Headers, HeaderMap, ProtectedHeaderMap, Int, BigNum, AlgorithmId, COSEKey, KeyType } = await (typeof window === "undefined" ? import("@emurgo/cardano-message-signing-nodejs") : import("@emurgo/cardano-message-signing-browser"));
	const protectedHeaders = HeaderMap.new();
	protectedHeaders.set_algorithm_id(Label.from_algorithm_id(AlgorithmId.EdDSA));
	protectedHeaders.set_header(Label.new_text("address"), CBORValue.new_bytes(fromHex(addressHex)));
	const protectedSerialized = ProtectedHeaderMap.new(protectedHeaders);
	const unprotectedHeaders = HeaderMap.new();
	const headers = Headers.new(protectedSerialized, unprotectedHeaders);
	const builder = COSESign1Builder.new(headers, fromHex(payload), false);
	const toSign = builder.make_data_to_sign().to_bytes();
	const publicKey = await privateKey.toPublic();
	const signedSigStruc = await privateKey.sign(HexBlob(toHex(toSign)));
	const coseSign1 = builder.build(signedSigStruc.bytes());
	const key = COSEKey.new(Label.from_key_type(KeyType.OKP));
	key.set_algorithm_id(Label.from_algorithm_id(AlgorithmId.EdDSA));
	key.set_header(Label.new_int(Int.new_negative(BigNum.from_str("1"))), CBORValue.new_int(Int.new_i32(6)));
	key.set_header(Label.new_int(Int.new_negative(BigNum.from_str("2"))), CBORValue.new_bytes(publicKey.bytes()));
	return {
		signature: HexBlob(toHex(coseSign1.to_bytes())),
		key: HexBlob(toHex(key.to_bytes()))
	};
}

